package vn.iotstar.config; import org.springframework.boot.web.servlet.FilterRegistrationBean; import org.springframework.context.annotation.*; import org.springframework.web.filter.CharacterEncodingFilter; @Configuration public class EncodingConfig{@Bean FilterRegistrationBean<CharacterEncodingFilter> characterEncodingFilter(){CharacterEncodingFilter f=new CharacterEncodingFilter();f.setEncoding("UTF-8");f.setForceEncoding(true);FilterRegistrationBean<CharacterEncodingFilter> r=new FilterRegistrationBean<>(f);r.setOrder(Integer.MIN_VALUE);return r;}}